rows = []
for i, (y, a, t, v, ty, topic, contrib, conf) in enumerate(B, 1):
    q = urllib.parse.quote_plus(f'{t} {a.split(",")[0]}')
    rows.append({'id': f'bib.{i:04d}', 'year': y, 'decade': f'{(y//10)*10}s', 'authors': a, 'title': t, 'venue': v, 'type': ty, 'topic': topic,
                 'key_contribution': contrib, 'citation': f'{a} ({y}). {t}. {v}.', 'find_url': 'https://scholar.google.com/scholar?q=' + q, 'confidence': conf})
with open(OUT + '/bibliography.jsonl', 'w') as f:
    for r in rows: f.write(json.dumps(r, ensure_ascii=False) + '\n')
print('bibliography', len(rows))
